import numpy as np
import heapq

# Read weights
with open('maze_weights.txt') as f:
    weights = [list(map(int, line.strip().split())) for line in f if line.strip()]
maze = np.array(weights)
N, M = maze.shape

# If maze is not 2D (edge case)
if len(maze.shape) != 2:
    print('Weight file malformed')
    exit(1)

def node_index(row, col):
    return row * M + col

def coord_from_index(idx):
    return (idx // M, idx % M)

def neighbors(r, c):
    for dr, dc, move in [(-1,0,'U'),(1,0,'D'),(0,-1,'L'),(0,1,'R')]:
        nr, nc = r+dr, c+dc
        if 0 <= nr < N and 0 <= nc < M and maze[nr][nc] != 0:
            yield nr, nc, maze[nr][nc], move

start = (0,0)
end_idx = 41
end = coord_from_index(end_idx)

def dijkstra(start, end):
    sr, sc = start
    tr, tc = end
    pq = [(0, sr, sc, node_index(sr, sc), [])]
    visited = set()
    while pq:
        cost, r, c, idx, path = heapq.heappop(pq)
        if (r, c) in visited:
            continue
        visited.add((r, c))
        new_path = path + [node_index(r, c)]
        if (r, c) == (tr, tc):
            return cost, new_path
        for nr, nc, w, move in neighbors(r, c):
            if (nr, nc) not in visited:
                heapq.heappush(pq, (cost+w, nr, nc, node_index(nr, nc), new_path))
    return None, None

cost, full_path = dijkstra(start, end)

csv = ','.join(map(str, full_path))
concat = ''.join(map(str, full_path))
dash = '-'.join(map(str, full_path))

# Generate movement directions
moves = []
for i in range(1, len(full_path)):
    r1, c1 = coord_from_index(full_path[i-1])
    r2, c2 = coord_from_index(full_path[i])
    if r2 == r1 and c2 == c1+1:
        moves.append('R')
    elif r2 == r1 and c2 == c1-1:
        moves.append('L')
    elif r2 == r1+1 and c2 == c1:
        moves.append('D')
    elif r2 == r1-1 and c2 == c1:
        moves.append('U')
move_str = ''.join(moves)

print(f"[*] Shortest path cost: {cost}\n[*] Node list: {full_path}")
print(f"[*] CSV: {csv}")
print(f"[*] Concat: {concat}")
print(f"[*] Dash: {dash}")
print(f"[*] Grid movement directions: {move_str if move_str else '<none>'}")

import torch
import numpy as np
import networkx as nx

def load_maze(path):
    obj = torch.load(path, map_location='cpu')
    if isinstance(obj, dict):
        # Try common keys
        for key in ['weight', 'maze', 'matrix', 'adj', 'data', 'adj_matrix']:
            if key in obj:
                arr = obj[key]
                if hasattr(arr, 'numpy'):
                    arr = arr.numpy()
                return arr
        # Try just using first big numpy array
        for v in obj.values():
            if hasattr(v, 'numpy') and len(v.shape) == 2:
                return v.numpy()
        raise Exception(f'Unknown keys in dict: {obj.keys()}')
    # May just be a tensor
    if hasattr(obj, 'numpy'):
        return obj.numpy()
    raise Exception('Unable to load maze matrix from file')

def build_graph(weight_matrix):
    G = nx.Graph()
    n = weight_matrix.shape[0]
    for i in range(n):
        for j in range(n):
            w = weight_matrix[i, j]
            if w > 0 and i != j:
                G.add_edge(i, j, weight=w)
    return G

def shortest_path_reps(G, start, end):
    path = nx.shortest_path(G, source=start, target=end, weight='weight')
    comma_sep = ','.join(map(str, path))
    concat = ''.join(map(str, path))
    dash_sep = '-'.join(map(str, path))
    return path, comma_sep, concat, dash_sep

def grid_directions(path, n_nodes):
    # Try grid shape: try square and rectangular factors
    N = int(np.ceil(np.sqrt(n_nodes)))
    h = n_nodes // N
    possible_shapes = [(N, h), (h, N)]
    for shape in possible_shapes:
        rows, cols = shape
        if rows * cols >= n_nodes:
            coords = [(p // cols, p % cols) for p in path]
            dirs = []
            for (x1,y1),(x2,y2) in zip(coords, coords[1:]):
                dx = x2 - x1
                dy = y2 - y1
                if dx == 1 and dy == 0:
                    dirs.append('D')
                elif dx == -1 and dy == 0:
                    dirs.append('U')
                elif dx == 0 and dy == 1:
                    dirs.append('R')
                elif dx == 0 and dy == -1:
                    dirs.append('L')
                else:
                    dirs.append('?')
            if '?' not in dirs:
                return shape, coords, ''.join(dirs)
    return None, None, None

def main():
    maze_path = '/home/ctfplayer/ctf_files/attachment/maze.pt'
    W = load_maze(maze_path)
    G = build_graph(W)
    n_nodes = W.shape[0]
    start, end = 0, 41
    path, comma, concat, dash = shortest_path_reps(G, start, end)
    print(f"Shortest path (comma-separated): {comma}")
    print(f"Shortest path (concat): {concat}")
    print(f"Shortest path (dash-separated): {dash}")
    print(f"Full index list: {path}")
    shape, coords, dirs = grid_directions(path, n_nodes)
    if shape:
        print(f"Grid shape: {shape}")
        print(f"Grid coords: {coords}")
        print(f"Movement directions: {dirs}")
    else:
        print("No meaningful grid mapping found.")

if __name__ == '__main__':
    main()

